var FT={"Crippling":{"cat":"F","hb":"VSS14","d":"When you hit a creature with a Melee weapon attack, its Speed drops by 10 feet (minimum 0) until the end of its next turn, and it cannot Dash until then.","full":"When you hit a creature with a Melee weapon attack, its Speed drops by 10 feet, to a minimum of 0, until the end of its next turn. It also cannot take the Dash action until the end of that turn.","fx":{"notes":[["Note","Crippling: a Melee weapon hit cuts the target's Speed by 10 ft and blocks its Dash until the end of its next turn"]]}},"Titan Fighting":{"cat":"F","hb":"VSS14","d":"+2 bonus to Melee weapon attack rolls against Large or larger creatures.","full":"You have a +2 bonus to Melee weapon attack rolls you make against creatures that are Large or larger.","fx":{"notes":[["Note","Titan Fighting: +2 to Melee weapon attack rolls against Large or larger creatures"]]}}};
